#!/usr/bin/env python3
"""Phase 4A installer for the Wines & Spirits POS: M-PESA payments (customer pays the Till directly, or STK push).

HOW TO USE
    1. Close the POS server.  2. Copy this file next to manage.py.  3. Run:   python phase4a_apply.py
    4. Then:   python manage.py makemigrations sales
               python manage.py migrate
               python manage.py collectstatic --noinput
       and fill the MPESA_* lines in .env (see .env.example).

WHAT IT DOES (and nothing else)
    * Adds the M-PESA modules, tests and PHASE4_NOTES.md.
    * Edits 12 existing files with exact-text replacements. If any file does not look the way this script expects,
      it stops BEFORE writing anything. Every file it changes is first copied to _phase4a_backup/.
    * UI: removes the red top border on the login card; removes the separate "I am the owner" button (the owner
      now signs in through the normal first step, and the second step is pre-filled with the owner's username).
Safe to run twice: it detects that it has already been applied.
"""
import pathlib
import shutil
import sys

ROOT = pathlib.Path(__file__).resolve().parent
MARK = "Phase 4A"

NEW_FILES = {
    'sales/mpesa_rules.py': '"""M-PESA rules with no Django in them (so they are fast to test and impossible to confuse with the database).\n\nWhat Safaricom really sends, and what we do with it:\n\n* C2B confirmation (customer pays the Till directly, or an STK push to the Till completes): has TransID (the\n  M-PESA receipt code), TransAmount, TransTime and, only sometimes, FirstName / MiddleName / LastName. Since\n  Safaricom\'s v2 API the phone number (MSISDN) is hashed, so it is NOT a usable phone number.\n* STK callback: has CheckoutRequestID, ResultCode and, on success, MpesaReceiptNumber + Amount + PhoneNumber.\n  It never carries a customer name.\n\nA name is stored ONLY if Safaricom sent one. Nothing is guessed. The cashier can still type one.\n"""\nimport base64\nimport re\nfrom decimal import Decimal, InvalidOperation\n\n\nclass MpesaError(ValueError):\n    pass\n\n\n# --- phone numbers ---------------------------------------------------------------------------------\n\ndef normalize_phone(raw):\n    """07xx / 01xx / +2547xx / 2547xx -> 2547XXXXXXXX (12 digits). Raises MpesaError if it is not a Kenyan mobile."""\n    digits = re.sub(r"[\\s\\-()+]", "", str(raw or ""))\n    if digits.startswith("0") and len(digits) == 10:\n        digits = "254" + digits[1:]\n    if not re.fullmatch(r"254[17]\\d{8}", digits):\n        raise MpesaError("Enter a Kenyan mobile number such as 0712 345 678.")\n    return digits\n\n\ndef phone_hint(value):\n    """Safe text to show a cashier: last 3 digits of a real number, or nothing for a hashed one."""\n    v = str(value or "")\n    return ("07xx xxx " + v[-3:]) if re.fullmatch(r"254[17]\\d{8}", v) else ""\n\n\n# --- names -----------------------------------------------------------------------------------------\n\ndef clean_name(*parts):\n    """Join FirstName/MiddleName/LastName. Returns \'\' unless it looks like a real name."""\n    words = [re.sub(r"\\s+", " ", str(p or "")).strip() for p in parts]\n    name = " ".join(w for w in words if w)\n    if len(name) < 2 or len(name) > 120:\n        return ""\n    if re.search(r"\\d", name) and not re.search(r"[A-Za-z]{2}", name):\n        return ""                                   # a phone number or a hash, not a name\n    if re.fullmatch(r"[0-9a-fA-F]{32,}", name.replace(" ", "")):\n        return ""                                   # SHA-256 style hash\n    if name.lower() in {"null", "none", "n/a", "na", "unknown", "-"}:\n        return ""\n    return name[:120]\n\n\ndef pick_customer_name(mpesa_name, typed_name=""):\n    """The name that goes on the sale: what the cashier typed wins, else the M-PESA name, else blank."""\n    return (str(typed_name or "").strip() or str(mpesa_name or "").strip())[:120]\n\n\n# --- amounts ---------------------------------------------------------------------------------------\n\ndef parse_amount(raw):\n    try:\n        value = Decimal(str(raw).replace(",", "").strip())\n    except (InvalidOperation, AttributeError):\n        raise MpesaError("Payment amount is missing or invalid.")\n    if value <= 0:\n        raise MpesaError("Payment amount must be more than zero.")\n    return value.quantize(Decimal("0.01"))\n\n\ndef stk_amount(total):\n    """STK Push accepts whole shillings only. A total with cents cannot be pushed; the customer pays at the Till."""\n    total = Decimal(total)\n    if total != total.to_integral_value():\n        raise MpesaError("STK push needs a whole-shillings total. Ask the customer to pay the exact amount to the Till.")\n    return int(total)\n\n\ndef amount_matches(paid, total):\n    """Exact match only. Under- and over-payments need the split/overpay handling of sub-phase 4B."""\n    return Decimal(paid) == Decimal(total)\n\n\n# --- Daraja request helpers ------------------------------------------------------------------------\n\ndef stk_password(shortcode, passkey, timestamp):\n    return base64.b64encode(f"{shortcode}{passkey}{timestamp}".encode()).decode()\n\n\ndef parse_c2b(payload):\n    """C2B confirmation JSON -> dict. Raises MpesaError when it has no receipt code or amount."""\n    if not isinstance(payload, dict):\n        raise MpesaError("Not a payment message.")\n    trans_id = str(payload.get("TransID") or "").strip().upper()\n    if not re.fullmatch(r"[A-Z0-9]{8,14}", trans_id):\n        raise MpesaError("Missing or invalid TransID.")\n    return {\n        "trans_id": trans_id,\n        "amount": parse_amount(payload.get("TransAmount")),\n        "customer_name": clean_name(payload.get("FirstName"), payload.get("MiddleName"), payload.get("LastName")),\n        "payer_ref": str(payload.get("MSISDN") or "")[:80],\n        "shortcode": str(payload.get("BusinessShortCode") or "")[:12],\n        "bill_ref": str(payload.get("BillRefNumber") or "")[:60],\n        "trans_time": str(payload.get("TransTime") or "")[:14],\n    }\n\n\ndef parse_stk_callback(payload):\n    """STK callback JSON -> dict with ok, checkout_request_id, result_code, result_desc and (if ok) receipt data."""\n    try:\n        cb = payload["Body"]["stkCallback"]\n        checkout = str(cb["CheckoutRequestID"])\n        code = int(cb["ResultCode"])\n    except (KeyError, TypeError, ValueError):\n        raise MpesaError("Not an STK callback.")\n    out = {"checkout_request_id": checkout, "merchant_request_id": str(cb.get("MerchantRequestID") or ""),\n           "result_code": code, "result_desc": str(cb.get("ResultDesc") or "")[:200], "ok": code == 0}\n    if code == 0:\n        items = {}\n        for it in (cb.get("CallbackMetadata") or {}).get("Item", []) or []:\n            if isinstance(it, dict) and "Name" in it:\n                items[it["Name"]] = it.get("Value")\n        receipt = str(items.get("MpesaReceiptNumber") or "").strip().upper()\n        if not re.fullmatch(r"[A-Z0-9]{8,14}", receipt):\n            raise MpesaError("Successful STK callback without a receipt number.")\n        out.update(trans_id=receipt, amount=parse_amount(items.get("Amount")),\n                   payer_ref=str(items.get("PhoneNumber") or "")[:80], trans_time=str(items.get("TransactionDate") or "")[:14])\n    return out\n\n\n# Result codes worth telling the cashier about (everything else shows Safaricom\'s own description).\nSTK_EXPIRED = {1037}                  # customer\'s phone did not respond in time\nSTK_CANCELLED = {1032}                # customer cancelled\nSTK_TERMINAL_FAILS = {1, 17, 1019, 1025, 1032, 1037, 2001, 9999}\n\n\ndef stk_failure_status(code):\n    """FAILED or EXPIRED for a non-zero result code."""\n    return "EXPIRED" if int(code) in STK_EXPIRED else "FAILED"\n',
    'sales/daraja.py': '"""Safaricom Daraja client (standard library only, no extra package). Credentials come from settings.MPESA,\nwhich reads .env; nothing is hardcoded. Every call has a timeout and returns plain dicts or raises DarajaError,\nso a dead internet connection never freezes a till: cash sales do not touch this module at all."""\nimport base64\nimport json\nimport urllib.error\nimport urllib.request\nfrom datetime import datetime\n\nfrom django.conf import settings\nfrom django.core.cache import cache\n\nfrom . import mpesa_rules as rules\n\nBASES = {"sandbox": "https://sandbox.safaricom.co.ke", "live": "https://api.safaricom.co.ke"}\n\n\nclass DarajaError(Exception):\n    pass\n\n\ndef cfg():\n    return settings.MPESA\n\n\ndef configured():\n    c = cfg()\n    return bool(c["CONSUMER_KEY"] and c["CONSUMER_SECRET"] and c["SHORTCODE"] and c["PASSKEY"] and c["CALLBACK_BASE_URL"]\n                and c["CALLBACK_SECRET"])\n\n\ndef callbacks_ready():\n    """The public callback address and its secret exist (needed for both STK and till payments)."""\n    c = cfg()\n    return bool(c["CALLBACK_BASE_URL"] and c["CALLBACK_SECRET"])\n\n\ndef callback_url(kind):\n    c = cfg()\n    return f"{c[\'CALLBACK_BASE_URL\'].rstrip(\'/\')}/api/pay/{kind}/{c[\'CALLBACK_SECRET\']}/"\n\n\ndef _call(method, path, body=None, headers=None):\n    url = BASES[cfg()["ENV"]] + path\n    data = json.dumps(body).encode() if body is not None else None\n    req = urllib.request.Request(url, data=data, method=method, headers=headers or {})\n    try:\n        with urllib.request.urlopen(req, timeout=cfg()["TIMEOUT"]) as resp:\n            return json.loads(resp.read().decode() or "{}")\n    except urllib.error.HTTPError as exc:\n        try:\n            detail = json.loads(exc.read().decode() or "{}")\n        except ValueError:\n            detail = {}\n        raise DarajaError(detail.get("errorMessage") or detail.get("ResponseDescription") or f"Safaricom error {exc.code}")\n    except (urllib.error.URLError, OSError, ValueError):\n        raise DarajaError("Cannot reach Safaricom right now (no internet?).")\n\n\ndef token():\n    c = cfg()\n    cached = cache.get("daraja-token")\n    if cached:\n        return cached\n    basic = base64.b64encode(f"{c[\'CONSUMER_KEY\']}:{c[\'CONSUMER_SECRET\']}".encode()).decode()\n    res = _call("GET", "/oauth/v1/generate?grant_type=client_credentials", headers={"Authorization": f"Basic {basic}"})\n    tok = res.get("access_token")\n    if not tok:\n        raise DarajaError("Safaricom did not give an access token. Check the consumer key and secret.")\n    cache.set("daraja-token", tok, 3000)          # tokens last 3600 s\n    return tok\n\n\ndef _auth():\n    return {"Authorization": f"Bearer {token()}", "Content-Type": "application/json"}\n\n\ndef _stamp():\n    return datetime.now().strftime("%Y%m%d%H%M%S")\n\n\ndef stk_push(phone, amount_whole, reference, description="Payment"):\n    """Ask the customer\'s phone for payment. Returns {merchant_request_id, checkout_request_id}."""\n    c = cfg()\n    if not configured():\n        raise DarajaError("M-PESA STK push is not configured. Customers can still pay the Till directly.")\n    ts = _stamp()\n    till = c["ACCOUNT_TYPE"] == "till"\n    body = {\n        "BusinessShortCode": c["SHORTCODE"],\n        "Password": rules.stk_password(c["SHORTCODE"], c["PASSKEY"], ts),\n        "Timestamp": ts,\n        "TransactionType": "CustomerBuyGoodsOnline" if till else "CustomerPayBillOnline",\n        "Amount": amount_whole, "PartyA": phone,\n        "PartyB": (c["TILL_NUMBER"] or c["SHORTCODE"]) if till else c["SHORTCODE"],\n        "PhoneNumber": phone, "CallBackURL": callback_url("stk"),\n        "AccountReference": str(reference)[:12], "TransactionDesc": str(description)[:13],\n    }\n    res = _call("POST", "/mpesa/stkpush/v1/processrequest", body, _auth())\n    if str(res.get("ResponseCode")) != "0" or not res.get("CheckoutRequestID"):\n        raise DarajaError(res.get("ResponseDescription") or res.get("errorMessage") or "Safaricom refused the request.")\n    return {"merchant_request_id": res.get("MerchantRequestID", ""), "checkout_request_id": res["CheckoutRequestID"]}\n\n\ndef stk_query(checkout_request_id):\n    """Ask Safaricom what happened to a push. Returns (result_code or None, description).\n    NOTE: this reply has no receipt number, so it may only be used to FAIL/EXPIRE a request early, never to\n    confirm money. Confirmation always comes from the callback with its M-PESA receipt."""\n    c = cfg()\n    ts = _stamp()\n    body = {"BusinessShortCode": c["SHORTCODE"], "Password": rules.stk_password(c["SHORTCODE"], c["PASSKEY"], ts),\n            "Timestamp": ts, "CheckoutRequestID": checkout_request_id}\n    try:\n        res = _call("POST", "/mpesa/stkpushquery/v1/query", body, _auth())\n    except DarajaError as exc:\n        if "processing" in str(exc).lower():\n            return None, "Still being processed."\n        raise\n    if "ResultCode" not in res:\n        return None, res.get("ResponseDescription", "")\n    return int(res["ResultCode"]), res.get("ResultDesc", "")\n\n\ndef register_c2b_urls():\n    """One-off: tell Safaricom where to send till/paybill payments. Run the command on the server that is public."""\n    c = cfg()\n    body = {"ShortCode": c["TILL_NUMBER"] or c["SHORTCODE"], "ResponseType": "Completed",\n            "ConfirmationURL": callback_url("c2b/confirm"), "ValidationURL": callback_url("c2b/validate")}\n    return _call("POST", "/mpesa/c2b/v2/registerurl", body, _auth())\n',
    'sales/mpesa_services.py': '"""M-PESA capture and matching. The rules in one place:\n\n* A payment is real ONLY when it arrives from Safaricom\'s callback with an M-PESA receipt code. A cashier\n  typing a code, or showing an SMS or screenshot, never confirms anything.\n* One receipt code = one MpesaTransaction (unique in the database) = at most one Payment (one-to-one).\n  Safaricom retries callbacks, so every handler is safe to run twice.\n* Callbacks can arrive in either order (STK result first, till/C2B message first). Both land on the same\n  row, keyed by the receipt code, and a customer name is filled in whenever a message carrying one arrives.\n* The cashier can only apply a payment whose amount equals the sale total exactly. Part payments, overpayments\n  and refunds are sub-phase 4B.\n"""\nfrom datetime import timedelta\n\nfrom django.db import IntegrityError, transaction\nfrom django.utils import timezone\n\nfrom core import audit\n\nfrom . import daraja, mpesa_rules as rules\nfrom . import services as sales_services\nfrom .models import MpesaStkRequest, MpesaTransaction, Payment, Sale\nfrom .services import SaleError\n\nRECENT_MINUTES = 90\n\n\n# --- callbacks (no user, no login: authenticated by the secret in the URL, see mpesa_views) -----------\n\ndef record_c2b(payload):\n    """A till / paybill payment confirmation. Returns (transaction, created)."""\n    p = rules.parse_c2b(payload)\n    with transaction.atomic():\n        txn, created = MpesaTransaction.objects.get_or_create(\n            trans_id=p["trans_id"],\n            defaults={"source": MpesaTransaction.C2B, "amount": p["amount"], "customer_name": p["customer_name"],\n                      "payer_ref": p["payer_ref"], "shortcode": p["shortcode"], "bill_ref": p["bill_ref"],\n                      "trans_time": p["trans_time"], "raw": payload})\n        if not created:\n            _enrich(txn, p["customer_name"], p["payer_ref"], p["shortcode"])\n    if created:\n        audit.record("mpesa.payment_received", object_type="mpesa", object_ref=txn.trans_id,\n                     new={"amount": str(txn.amount), "source": "C2B", "named": bool(txn.customer_name)})\n    return txn, created\n\n\ndef _enrich(txn, name, payer_ref="", shortcode=""):\n    """A later message about the same receipt may carry what the first one lacked. Never overwrite, never edit the amount."""\n    fields = []\n    if name and not txn.customer_name:\n        txn.customer_name = name; fields.append("customer_name")\n    if payer_ref and not txn.payer_ref:\n        txn.payer_ref = payer_ref; fields.append("payer_ref")\n    if shortcode and not txn.shortcode:\n        txn.shortcode = shortcode; fields.append("shortcode")\n    if fields:\n        txn.save(update_fields=fields + ["updated_at"])\n\n\ndef record_stk_callback(payload):\n    """Result of an STK push. Returns the MpesaStkRequest, or None if we never asked for it (logged)."""\n    p = rules.parse_stk_callback(payload)\n    with transaction.atomic():\n        stk = (MpesaStkRequest.objects.select_for_update().filter(checkout_request_id=p["checkout_request_id"]).first())\n        if stk is None:\n            audit.record("mpesa.unknown_stk_callback", object_type="mpesa", object_ref=p["checkout_request_id"],\n                         new={"code": p["result_code"]})\n            return None\n        if stk.status in (MpesaStkRequest.CONFIRMED, MpesaStkRequest.FAILED, MpesaStkRequest.EXPIRED):\n            return stk                                   # Safaricom retried; nothing more to do\n        stk.result_code, stk.result_desc = p["result_code"], p["result_desc"]\n        if p["ok"]:\n            txn, _ = MpesaTransaction.objects.get_or_create(\n                trans_id=p["trans_id"],\n                defaults={"source": MpesaTransaction.STK, "amount": p["amount"], "payer_ref": p["payer_ref"],\n                          "trans_time": p["trans_time"], "raw": payload})\n            _enrich(txn, "", p["payer_ref"])\n            stk.status, stk.transaction = MpesaStkRequest.CONFIRMED, txn\n        else:\n            stk.status = rules.stk_failure_status(p["result_code"])\n        stk.save()\n    audit.record("mpesa.stk_result", object_type="mpesa", object_ref=stk.checkout_request_id,\n                 new={"status": stk.status, "code": stk.result_code})\n    return stk\n\n\n# --- cashier actions ------------------------------------------------------------------------------\n\ndef _cart_total(user, shift):\n    sale = sales_services.active_sale(user, shift)\n    if sale is None or not sale.items.exists():\n        raise SaleError("The sale is empty.")\n    total = sales_services.cart_total(sale)\n    if total <= 0:\n        raise SaleError("The total must be more than zero.")\n    return sale, total\n\n\ndef start_stk(user, shift, phone):\n    sales_services._need(user, "sales.make")\n    sales_services._need(user, "payments.accept", "You are not allowed to accept payments.")\n    sales_services._shift_still_open(shift)\n    sale, total = _cart_total(user, shift)\n    try:\n        number = rules.normalize_phone(phone)\n        whole = rules.stk_amount(total)\n    except rules.MpesaError as exc:\n        raise SaleError(str(exc)) from exc\n    live = MpesaStkRequest.objects.filter(sale=sale, status__in=MpesaStkRequest.OPEN_STATES,\n                                          created_at__gte=timezone.now() - timedelta(seconds=90)).first()\n    if live:\n        raise SaleError("A request was just sent to this customer. Wait for them to enter their PIN or for it to expire.")\n    stk = MpesaStkRequest.objects.create(sale=sale, cashier=user, shift=shift, phone=number, amount=total)\n    try:\n        res = daraja.stk_push(number, whole, reference=f"T{shift.till.number}-{sale.pk}")\n    except daraja.DarajaError as exc:\n        stk.status, stk.result_desc = MpesaStkRequest.FAILED, str(exc)[:200]\n        stk.save(update_fields=["status", "result_desc", "updated_at"])\n        raise SaleError(str(exc)) from exc\n    stk.merchant_request_id, stk.checkout_request_id = res["merchant_request_id"], res["checkout_request_id"]\n    stk.status = MpesaStkRequest.PROCESSING\n    stk.save(update_fields=["merchant_request_id", "checkout_request_id", "status", "updated_at"])\n    audit.record("mpesa.stk_sent", actor=user, object_type="sale", object_ref=sale.pk, new={"amount": str(total)},\n                 till_number=shift.till.number)\n    return stk\n\n\ndef stk_status(user, shift, stk_id):\n    """What the screen polls. If the callback is late (or lost) we may ask Safaricom, but only to fail/expire."""\n    stk = MpesaStkRequest.objects.select_related("transaction").filter(pk=stk_id, cashier=user, shift=shift).first()\n    if stk is None:\n        raise SaleError("Unknown payment request.")\n    if stk.status == MpesaStkRequest.PROCESSING and stk.checkout_request_id and \\\n            timezone.now() - stk.created_at > timedelta(seconds=25) and daraja.configured():\n        try:\n            code, desc = daraja.stk_query(stk.checkout_request_id)\n        except daraja.DarajaError:\n            code = None\n        if code not in (None, 0):\n            stk.status, stk.result_code, stk.result_desc = rules.stk_failure_status(code), code, desc[:200]\n            stk.save(update_fields=["status", "result_code", "result_desc", "updated_at"])\n        elif timezone.now() - stk.created_at > timedelta(minutes=3):\n            stk.status = MpesaStkRequest.EXPIRED\n            stk.result_desc = "No answer from the customer\'s phone."\n            stk.save(update_fields=["status", "result_desc", "updated_at"])\n    elif stk.status == MpesaStkRequest.PROCESSING and timezone.now() - stk.created_at > timedelta(minutes=3):\n        stk.status, stk.result_desc = MpesaStkRequest.EXPIRED, "No answer from the customer\'s phone."\n        stk.save(update_fields=["status", "result_desc", "updated_at"])\n    return stk\n\n\ndef recent_unmatched(user, shift, total=None):\n    """Confirmed payments that no sale has used yet (newest first). With `total`, only exact matches."""\n    sales_services._need(user, "payments.accept", "You are not allowed to accept payments.")\n    since = timezone.now() - timedelta(minutes=RECENT_MINUTES)\n    qs = MpesaTransaction.objects.filter(status=MpesaTransaction.UNMATCHED, created_at__gte=since).order_by("-created_at")\n    if total is not None:\n        qs = qs.filter(amount=total)\n    return list(qs[:12])\n\n\n@transaction.atomic\ndef checkout_mpesa(user, shift, transaction_id):\n    """Complete the sale with a payment Safaricom has already confirmed to us."""\n    sales_services._need(user, "sales.make")\n    sales_services._need(user, "payments.accept", "You are not allowed to accept payments.")\n    sales_services._shift_still_open(shift)\n    sale, total = _cart_total(user, shift)\n    txn = MpesaTransaction.objects.select_for_update().filter(pk=transaction_id).first()\n    if txn is None:\n        raise SaleError("That payment was not found.")\n    if txn.status != MpesaTransaction.UNMATCHED:\n        raise SaleError("That M-PESA payment has already been used on another sale.")\n    if not rules.amount_matches(txn.amount, total):\n        raise SaleError(f"That payment is KES {txn.amount} but this sale is KES {total}. "\n                        "Part payments and overpayments are handled in the next update.")\n    name = rules.pick_customer_name(txn.customer_name, sale.customer_name)\n    done = sales_services.finish_sale(user, shift, payment={\n        "method": Payment.MPESA, "reference": txn.trans_id, "mpesa_transaction": txn}, customer_name=name)\n    txn.status, txn.sale = MpesaTransaction.MATCHED, done\n    txn.matched_by, txn.matched_at = user, timezone.now()\n    txn.save(update_fields=["status", "sale", "matched_by", "matched_at", "updated_at"])\n    audit.record("mpesa.payment_applied", actor=user, object_type="sale", object_ref=done.number,\n                 new={"receipt": txn.trans_id, "amount": str(txn.amount), "name_from_mpesa": bool(txn.customer_name)},\n                 till_number=shift.till.number)\n    return done\n',
    'sales/mpesa_views.py': '"""Public callback endpoints for Safaricom (no login, no CSRF: Safaricom cannot do either). The only\nprotection is the long random secret in the address (MPESA_CALLBACK_SECRET) plus the strict parsing in\nmpesa_rules; do not publish the address. These must be reachable on a public HTTPS address (see README).\nSafaricom is always answered "accepted" for well-formed calls so it does not retry forever; money is\nrecorded exactly once because of the database\'s unique receipt code."""\nimport hmac\nimport json\n\nfrom django.conf import settings\nfrom django.http import Http404, JsonResponse\nfrom django.views.decorators.csrf import csrf_exempt\nfrom django.views.decorators.http import require_POST\n\nfrom . import mpesa_rules as rules\nfrom . import mpesa_services as svc\n\nACK = {"ResultCode": 0, "ResultDesc": "Accepted"}\nMAX_BODY = 64 * 1024\n\n\ndef _check(secret):\n    expected = settings.MPESA["CALLBACK_SECRET"]\n    if not expected or not hmac.compare_digest(str(secret), expected):\n        raise Http404()\n\n\ndef _payload(request):\n    if len(request.body) > MAX_BODY:\n        raise rules.MpesaError("Too large.")\n    try:\n        return json.loads(request.body.decode("utf-8"))\n    except (ValueError, UnicodeDecodeError):\n        raise rules.MpesaError("Not JSON.")\n\n\n@csrf_exempt\n@require_POST\ndef c2b_validate(request, secret):\n    _check(secret)\n    return JsonResponse(ACK)          # we accept every payment to the till; matching happens at the counter\n\n\n@csrf_exempt\n@require_POST\ndef c2b_confirm(request, secret):\n    _check(secret)\n    try:\n        svc.record_c2b(_payload(request))\n    except rules.MpesaError:\n        return JsonResponse({"ResultCode": 1, "ResultDesc": "Rejected"}, status=400)\n    return JsonResponse(ACK)\n\n\n@csrf_exempt\n@require_POST\ndef stk_result(request, secret):\n    _check(secret)\n    try:\n        svc.record_stk_callback(_payload(request))\n    except rules.MpesaError:\n        return JsonResponse({"ResultCode": 1, "ResultDesc": "Rejected"}, status=400)\n    return JsonResponse(ACK)\n',
    'sales/mpesa_urls.py': 'from django.urls import path\n\nfrom . import mpesa_views as v\n\n# Safaricom refuses callback addresses that contain words like "mpesa" or "safaricom", hence /api/pay/.\nurlpatterns = [\n    path("c2b/validate/<str:secret>/", v.c2b_validate, name="pay-c2b-validate"),\n    path("c2b/confirm/<str:secret>/", v.c2b_confirm, name="pay-c2b-confirm"),\n    path("stk/<str:secret>/", v.stk_result, name="pay-stk"),\n]\n',
    'sales/management/commands/mpesa_register_urls.py': 'from django.core.management.base import BaseCommand, CommandError\n\nfrom sales import daraja\n\n\nclass Command(BaseCommand):\n    help = "Register the till/paybill confirmation and validation URLs with Safaricom (run once, on the public server)."\n\n    def handle(self, *args, **options):\n        if not daraja.configured():\n            raise CommandError("Fill in the MPESA_* settings in .env first (see .env.example).")\n        try:\n            result = daraja.register_c2b_urls()\n        except daraja.DarajaError as exc:\n            raise CommandError(str(exc))\n        self.stdout.write(self.style.SUCCESS(f"Safaricom replied: {result}"))\n',
    'sales/test_phase4a.py': '"""Phase 4A tests: M-PESA capture, idempotent callbacks, customer name, exact-match checkout."""\nimport json\nfrom decimal import Decimal as D\n\nfrom django.test import Client, override_settings\n\nfrom . import mpesa_services as ms\nfrom .models import MpesaStkRequest, MpesaTransaction, Payment, Sale\nfrom .tests import SalesCase\n\nSECRET = "s3cret-callback-path"\nCFG = {"ENV": "sandbox", "CONSUMER_KEY": "", "CONSUMER_SECRET": "", "SHORTCODE": "", "TILL_NUMBER": "", "PASSKEY": "",\n       "ACCOUNT_TYPE": "till", "CALLBACK_BASE_URL": "https://pos.example.com", "CALLBACK_SECRET": SECRET, "TIMEOUT": 5}\n\n\ndef c2b(trans_id="SGL1ABC23D", amount="3500.00", first="JOHN", last="KAMAU"):\n    return {"TransactionType": "Pay Bill", "TransID": trans_id, "TransTime": "20261107201500", "TransAmount": amount,\n            "BusinessShortCode": "123456", "BillRefNumber": "", "MSISDN": "f" * 64,\n            "FirstName": first, "MiddleName": "", "LastName": last}\n\n\ndef stk_ok(checkout="ws_CO_1", receipt="SGL1ABC23D", amount=3500):\n    return {"Body": {"stkCallback": {"MerchantRequestID": "m1", "CheckoutRequestID": checkout, "ResultCode": 0,\n            "ResultDesc": "ok", "CallbackMetadata": {"Item": [\n                {"Name": "Amount", "Value": amount}, {"Name": "MpesaReceiptNumber", "Value": receipt},\n                {"Name": "TransactionDate", "Value": 20261107201500}, {"Name": "PhoneNumber", "Value": 254712345678}]}}}}\n\n\n@override_settings(MPESA=CFG)\nclass MpesaCaptureTests(SalesCase):\n    def post(self, kind, payload, secret=SECRET):\n        return Client().post(f"/api/pay/{kind}/{secret}/", json.dumps(payload), content_type="application/json")\n\n    def test_wrong_secret_is_404_and_records_nothing(self):\n        self.assertEqual(self.post("c2b/confirm", c2b(), secret="nope").status_code, 404)\n        self.assertEqual(MpesaTransaction.objects.count(), 0)\n\n    def test_same_callback_twice_records_one_payment(self):\n        for _ in range(3):\n            self.assertEqual(self.post("c2b/confirm", c2b()).json()["ResultCode"], 0)\n        self.assertEqual(MpesaTransaction.objects.count(), 1)\n\n    def test_garbage_is_rejected_not_recorded(self):\n        self.assertEqual(self.post("c2b/confirm", {"TransID": ""}).status_code, 400)\n        self.assertEqual(MpesaTransaction.objects.count(), 0)\n\n    def test_name_is_kept_and_not_invented(self):\n        self.post("c2b/confirm", c2b(first="", last=""))\n        self.assertEqual(MpesaTransaction.objects.get().customer_name, "")\n\n    def test_name_arrives_after_stk_result(self):\n        self.scan()\n        stk = MpesaStkRequest.objects.create(sale=Sale.objects.get(status="OPEN"), cashier=self.cashier, shift=self.shift,\n                                             phone="254712345678", amount=D("3500"), checkout_request_id="ws_CO_1",\n                                             status=MpesaStkRequest.PROCESSING)\n        self.post("stk", stk_ok())\n        self.assertEqual(MpesaTransaction.objects.get().customer_name, "")\n        self.post("c2b/confirm", c2b())                      # the till message with the name comes second\n        txn = MpesaTransaction.objects.get()\n        self.assertEqual((txn.customer_name, MpesaTransaction.objects.count()), ("JOHN KAMAU", 1))\n        stk.refresh_from_db()\n        self.assertEqual((stk.status, stk.transaction_id), (MpesaStkRequest.CONFIRMED, txn.pk))\n\n    def test_stk_retry_does_not_change_anything(self):\n        self.scan()\n        MpesaStkRequest.objects.create(sale=Sale.objects.get(status="OPEN"), cashier=self.cashier, shift=self.shift,\n                                       phone="254712345678", amount=D("3500"), checkout_request_id="ws_CO_1",\n                                       status=MpesaStkRequest.PROCESSING)\n        for _ in range(2):\n            self.post("stk", stk_ok())\n        self.assertEqual(MpesaTransaction.objects.count(), 1)\n\n    def test_unknown_stk_callback_creates_no_payment(self):\n        self.post("stk", stk_ok(checkout="never-asked"))\n        self.assertEqual(MpesaTransaction.objects.count(), 0)\n\n\n@override_settings(MPESA=CFG)\nclass MpesaCheckoutTests(SalesCase):\n    def paid(self, amount="3500.00", name="JOHN KAMAU", trans_id="SGL1ABC23D"):\n        return MpesaTransaction.objects.create(trans_id=trans_id, source="C2B", amount=D(amount), customer_name=name)\n\n    def test_checkout_uses_confirmed_payment_and_takes_name(self):\n        self.scan()\n        txn = self.paid()\n        sale = ms.checkout_mpesa(self.cashier, self.shift, txn.pk)\n        pay = sale.payments.get()\n        self.assertEqual((pay.method, pay.reference, pay.amount, sale.customer_name),\n                         (Payment.MPESA, "SGL1ABC23D", D("3500.00"), "JOHN KAMAU"))\n        txn.refresh_from_db()\n        self.assertEqual((txn.status, txn.sale_id), (MpesaTransaction.MATCHED, sale.pk))\n        self.assertEqual(self.stock(), 9)\n\n    def test_typed_name_is_not_overwritten(self):\n        sale, _ = self.scan()\n        from . import services\n        services.set_customer(self.cashier, self.shift, "Mr Otieno")\n        done = ms.checkout_mpesa(self.cashier, self.shift, self.paid().pk)\n        self.assertEqual(done.customer_name, "Mr Otieno")\n\n    def test_one_payment_cannot_pay_two_sales(self):\n        self.scan()\n        txn = self.paid()\n        ms.checkout_mpesa(self.cashier, self.shift, txn.pk)\n        self.scan()\n        with self.assertRaises(ms.SaleError):\n            ms.checkout_mpesa(self.cashier, self.shift, txn.pk)\n        self.assertEqual(Payment.objects.count(), 1)\n\n    def test_wrong_amount_is_refused_and_nothing_is_sold(self):\n        self.scan()\n        for amount in ("3499.00", "3501.00"):\n            with self.assertRaises(ms.SaleError):\n                ms.checkout_mpesa(self.cashier, self.shift, self.paid(amount, trans_id="X" + amount[:4] + "ABCDEF").pk)\n        self.assertEqual((self.stock(), Payment.objects.count()), (10, 0))\n\n    def test_mpesa_is_never_counted_as_cash_in_the_drawer(self):\n        from . import services\n        self.scan()\n        ms.checkout_mpesa(self.cashier, self.shift, self.paid().pk)\n        summary = services.shift_summary(self.shift)\n        self.assertEqual((summary["cash_sales"], summary["mpesa_sales"]), ("0.00", "3500.00"))\n        self.assertEqual(summary["cash_in_drawer_expected"], "5000.00")        # only the opening float\n\n    def test_recent_list_shows_only_unused_payments(self):\n        self.scan()\n        used, free = self.paid(trans_id="USEDABC123"), self.paid(trans_id="FREEABC123")\n        ms.checkout_mpesa(self.cashier, self.shift, used.pk)\n        self.scan()\n        self.assertEqual([t.trans_id for t in ms.recent_unmatched(self.cashier, self.shift)], ["FREEABC123"])\n',
    'tests_pure/test_phase4a_rules.py': 'import unittest\nfrom decimal import Decimal\n\nfrom sales import mpesa_rules as r\n\n\nclass Phone(unittest.TestCase):\n    def test_formats(self):\n        for raw in ("0712345678", "+254712345678", "254712345678", "0712 345 678", "0112345678"):\n            self.assertTrue(r.normalize_phone(raw).startswith("254"))\n        self.assertEqual(r.normalize_phone("0712345678"), "254712345678")\n\n    def test_bad(self):\n        for raw in ("", "12345", "0612345678", "25471234567", "abc"):\n            with self.assertRaises(r.MpesaError):\n                r.normalize_phone(raw)\n\n    def test_hint_never_shows_hash(self):\n        self.assertEqual(r.phone_hint("254712345678"), "07xx xxx 678")\n        self.assertEqual(r.phone_hint("a" * 64), "")\n\n\nclass Names(unittest.TestCase):\n    def test_real_name(self):\n        self.assertEqual(r.clean_name("JOHN", "", "KAMAU"), "JOHN KAMAU")\n\n    def test_not_names(self):\n        for parts in ((), ("",), ("254712345678",), ("null",), ("a" * 64,), ("7",)):\n            self.assertEqual(r.clean_name(*parts), "")\n\n    def test_typed_name_wins(self):\n        self.assertEqual(r.pick_customer_name("JOHN KAMAU", "Mr Otieno"), "Mr Otieno")\n        self.assertEqual(r.pick_customer_name("JOHN KAMAU", ""), "JOHN KAMAU")\n        self.assertEqual(r.pick_customer_name("", ""), "")\n\n\nclass Amounts(unittest.TestCase):\n    def test_exact_only(self):\n        self.assertTrue(r.amount_matches(Decimal("1500.00"), Decimal("1500")))\n        self.assertFalse(r.amount_matches(Decimal("1499.00"), Decimal("1500")))\n        self.assertFalse(r.amount_matches(Decimal("1501.00"), Decimal("1500")))\n\n    def test_stk_whole_shillings(self):\n        self.assertEqual(r.stk_amount(Decimal("1500.00")), 1500)\n        with self.assertRaises(r.MpesaError):\n            r.stk_amount(Decimal("1500.50"))\n\n    def test_parse(self):\n        self.assertEqual(r.parse_amount("1,500"), Decimal("1500.00"))\n        for bad in ("", "0", "-5", "x"):\n            with self.assertRaises(r.MpesaError):\n                r.parse_amount(bad)\n\n\nclass Payloads(unittest.TestCase):\n    C2B = {"TransactionType": "Pay Bill", "TransID": "SGL1ABC23D", "TransTime": "20261107201500",\n           "TransAmount": "1500.00", "BusinessShortCode": "123456", "BillRefNumber": "",\n           "MSISDN": "a" * 64, "FirstName": "JOHN", "MiddleName": "", "LastName": "KAMAU"}\n\n    def test_c2b(self):\n        p = r.parse_c2b(self.C2B)\n        self.assertEqual((p["trans_id"], p["amount"], p["customer_name"]), ("SGL1ABC23D", Decimal("1500.00"), "JOHN KAMAU"))\n\n    def test_c2b_without_name_is_blank_not_invented(self):\n        d = dict(self.C2B, FirstName="", LastName="")\n        self.assertEqual(r.parse_c2b(d)["customer_name"], "")\n\n    def test_c2b_rejects_junk(self):\n        for d in ({}, dict(self.C2B, TransID=""), dict(self.C2B, TransAmount="0"), "x"):\n            with self.assertRaises(r.MpesaError):\n                r.parse_c2b(d)\n\n    def stk(self, code=0, receipt="SGL1ABC23D"):\n        cb = {"MerchantRequestID": "m1", "CheckoutRequestID": "ws_CO_1", "ResultCode": code, "ResultDesc": "x"}\n        if code == 0:\n            cb["CallbackMetadata"] = {"Item": [{"Name": "Amount", "Value": 1500.0},\n                                               {"Name": "MpesaReceiptNumber", "Value": receipt},\n                                               {"Name": "TransactionDate", "Value": 20261107201500},\n                                               {"Name": "PhoneNumber", "Value": 254712345678}]}\n        return {"Body": {"stkCallback": cb}}\n\n    def test_stk_ok(self):\n        p = r.parse_stk_callback(self.stk())\n        self.assertTrue(p["ok"]); self.assertEqual(p["trans_id"], "SGL1ABC23D"); self.assertEqual(p["amount"], Decimal("1500.00"))\n        self.assertNotIn("customer_name", p)\n\n    def test_stk_failed(self):\n        p = r.parse_stk_callback(self.stk(1032))\n        self.assertFalse(p["ok"]); self.assertEqual(r.stk_failure_status(1032), "FAILED"); self.assertEqual(r.stk_failure_status(1037), "EXPIRED")\n\n    def test_stk_success_without_receipt_refused(self):\n        with self.assertRaises(r.MpesaError):\n            r.parse_stk_callback(self.stk(receipt=""))\n\n    def test_stk_junk(self):\n        with self.assertRaises(r.MpesaError):\n            r.parse_stk_callback({"Body": {}})\n\n    def test_password(self):\n        self.assertEqual(r.stk_password("174379", "pass", "20260101000000"), "MTc0Mzc5cGFzczIwMjYwMTAxMDAwMDAw")\n\n\nif __name__ == "__main__":\n    unittest.main()\n',
    'PHASE4_NOTES.md': '# Phase 4: Payments and refunds, in sub-phases\n\n## Sub-phase 4A (this update): capture M-PESA money\n\n**Done**\n\n- Customer pays the **Till directly**: Safaricom\'s till confirmation arrives, is stored once (unique M-PESA receipt code), and shows on the\n  cashier\'s M-PESA screen (F8, then 2). The cashier picks it and the sale completes.\n- **STK push**: the cashier types the customer\'s phone, the customer enters their PIN, Safaricom\'s callback confirms, the sale completes by itself.\n- **Customer name** is taken from Safaricom\'s till message (FirstName / MiddleName / LastName) and printed on the receipt. If Safaricom sends no\n  name it stays blank and the cashier can type one (Alt+C); a typed name always wins. Nothing is invented.\n- **No duplicates**: one receipt code = one payment record = at most one sale (database constraints). Safaricom retrying a callback changes nothing.\n- **Never trusts the cashier**: a payment exists only if Safaricom\'s callback created it. A screenshot, SMS or typed code confirms nothing.\n- Exact amount only. A KES 1,400 payment cannot close a KES 1,500 sale.\n- M-PESA is kept apart from cash: the shift summary has its own `mpesa_sales` figure and the expected drawer cash counts only cash.\n- Login: the red top border is gone; the separate "I am the owner" button is gone (owner uses the normal first step, second step is pre-filled).\n\n**What Safaricom does and does not give us (important)**\n\n- The STK callback has **no customer name**. Only the till/C2B confirmation can carry one, and even then it can be blank. Since the v2 API the phone\n  number in that message is **hashed**, so the screen shows "07xx xxx 678" only for STK payments.\n- An STK push to a Till normally also triggers the till confirmation, so the name usually arrives as a second message for the same receipt code.\n  Both messages land on the same row in either order. If your till never sends names, that is Safaricom\'s side, not a fault here.\n\n**Server setup (once)**\n\n1. Safaricom must reach a public HTTPS address. Run this same project on the VPS (its own database is fine for 4A), set `MPESA_CALLBACK_BASE_URL`\n   and a long random `MPESA_CALLBACK_SECRET`, then run `python manage.py mpesa_register_urls` there.\n2. Callback paths are `/api/pay/...` on purpose: Safaricom rejects addresses that contain words like "mpesa" or "safaricom".\n3. **Gap to know about:** the shop PC only sees a payment if the callback reaches *its* database. Until 4B, either run the shop server so it is\n   reachable from the internet (HTTPS tunnel), or treat the VPS as the server. Cash sales never depend on any of this.\n\n**Not tested here:** the Django tests (`sales/test_phase4a.py`) and the migration could not be run in the build environment (no Django install, no\ninternet). The framework-free tests in `tests_pure/test_phase4a_rules.py` pass (17). Nothing was tried against Safaricom\'s sandbox.\nRun: `makemigrations sales`, `migrate`, then `DB_ENGINE=sqlite DJANGO_DEBUG=true python manage.py test sales`, and send me any failure.\n\n## Sub-phase 4B (next update)\n\n1. **Refunds**: request, supervisor/manager approval (cashier cannot approve own), linked to the original sale, full or partial, reason, refund\n   receipt. M-PESA refunds track *approved* and *actually paid back* as separate statuses. Return to stock only if approved and resaleable.\n   eTIMS credit note (type R). Refunds shown in cash-up separate from cash.\n2. **Relay for offline shops**: the VPS stores callbacks, the shop PC pulls them when online (`mpesa_pull`), statuses OFFLINE_PENDING and UNMATCHED,\n   so a payment made while the shop\'s internet was down still arrives later.\n3. **Reconciliation screen**: payments received but not used, manager can assign or mark as ignored with a reason, everything audited.\n4. **Part payments, overpayments, split payments** (cash + M-PESA on one sale), **card** and **bank transfer**.\n5. **Name fallback**: Safaricom Transaction Status query when a payment has no name; auto-match when exactly one unused payment equals the cart total.\n6. `harden_db` triggers for the M-PESA tables, an M-PESA line in the F11 shift summary, and Safaricom IP allow-listing notes for the VPS.\n\nPhase 5 (cash-up, reports) then reads the separated cash / M-PESA / other figures already recorded here.\n',
}

MODELS_APPEND = '\n\nclass MpesaTransaction(models.Model):\n    """One confirmed M-PESA payment, keyed by Safaricom\'s receipt code. The unique code is what makes callbacks\n    idempotent: Safaricom may deliver the same message many times and only one row can ever exist.\n    Rows are history: the amount and code cannot change, and nothing is deleted."""\n\n    C2B, STK = "C2B", "STK"\n    SOURCES = [(C2B, "Paid to the Till / Paybill"), (STK, "STK push")]\n    UNMATCHED, MATCHED = "UNMATCHED", "MATCHED"\n    STATUSES = [(UNMATCHED, "Received, not yet used on a sale"), (MATCHED, "Used on a sale")]\n\n    trans_id = models.CharField("M-PESA receipt code", max_length=14, unique=True)\n    source = models.CharField(max_length=3, choices=SOURCES)\n    status = models.CharField(max_length=10, choices=STATUSES, default=UNMATCHED, db_index=True)\n    amount = models.DecimalField(max_digits=12, decimal_places=2)\n    # Only what Safaricom sent. Blank when it did not; the cashier may type a name on the sale instead.\n    customer_name = models.CharField(max_length=120, blank=True)\n    payer_ref = models.CharField(max_length=80, blank=True, help_text="Phone (STK) or Safaricom\'s hashed number (till).")\n    shortcode = models.CharField(max_length=12, blank=True)\n    bill_ref = models.CharField(max_length=60, blank=True)\n    trans_time = models.CharField(max_length=14, blank=True)\n    raw = models.JSONField(default=dict, blank=True)\n    sale = models.ForeignKey(Sale, null=True, blank=True, on_delete=models.PROTECT, related_name="mpesa_transactions")\n    matched_by = models.ForeignKey(settings.AUTH_USER_MODEL, null=True, blank=True, on_delete=models.PROTECT, related_name="+")\n    matched_at = models.DateTimeField(null=True, blank=True)\n    created_at = models.DateTimeField(auto_now_add=True, db_index=True)\n    updated_at = models.DateTimeField(auto_now=True)\n\n    class Meta:\n        ordering = ["-created_at", "-id"]\n        constraints = [models.CheckConstraint(condition=Q(amount__gt=0), name="mpesa_amount_positive")]\n\n    def __str__(self):\n        return f"{self.trans_id} KES {self.amount}"\n\n    @classmethod\n    def from_db(cls, db, field_names, values):\n        obj = super().from_db(db, field_names, values)\n        obj._orig = (obj.__dict__.get("trans_id"), obj.__dict__.get("amount"))\n        return obj\n\n    def save(self, *args, **kwargs):\n        if not self._state.adding and getattr(self, "_orig", None) and (self.trans_id, self.amount) != self._orig:\n            raise PermissionError("An M-PESA receipt code and amount cannot be changed.")\n        super().save(*args, **kwargs)\n        self._orig = (self.trans_id, self.amount)\n\n    def delete(self, *args, **kwargs):\n        raise PermissionError("M-PESA payment records cannot be deleted.")\n\n\nclass MpesaStkRequest(models.Model):\n    """A payment prompt sent to a customer\'s phone. It only ever becomes CONFIRMED from Safaricom\'s callback."""\n\n    PENDING, PROCESSING, CONFIRMED, FAILED, EXPIRED = "PENDING", "PROCESSING", "CONFIRMED", "FAILED", "EXPIRED"\n    STATUSES = [(PENDING, "Not sent yet"), (PROCESSING, "Waiting for the customer"), (CONFIRMED, "Paid"),\n                (FAILED, "Failed or cancelled"), (EXPIRED, "No answer")]\n    OPEN_STATES = (PENDING, PROCESSING)\n\n    sale = models.ForeignKey(Sale, on_delete=models.PROTECT, related_name="stk_requests")\n    cashier = models.ForeignKey(settings.AUTH_USER_MODEL, on_delete=models.PROTECT, related_name="+")\n    shift = models.ForeignKey("tills.CashierShift", on_delete=models.PROTECT, related_name="+")\n    phone = models.CharField(max_length=12)\n    amount = models.DecimalField(max_digits=12, decimal_places=2)\n    merchant_request_id = models.CharField(max_length=60, blank=True)\n    checkout_request_id = models.CharField(max_length=80, unique=True, null=True, blank=True)\n    status = models.CharField(max_length=10, choices=STATUSES, default=PENDING, db_index=True)\n    result_code = models.IntegerField(null=True, blank=True)\n    result_desc = models.CharField(max_length=200, blank=True)\n    transaction = models.ForeignKey(MpesaTransaction, null=True, blank=True, on_delete=models.PROTECT, related_name="stk_requests")\n    created_at = models.DateTimeField(auto_now_add=True)\n    updated_at = models.DateTimeField(auto_now=True)\n\n    class Meta:\n        ordering = ["-created_at", "-id"]\n\n    def __str__(self):\n        return f"STK {self.amount} to {self.phone[-3:]} ({self.get_status_display()})"\n\n    def delete(self, *args, **kwargs):\n        raise PermissionError("Payment requests cannot be deleted.")\n'
SETTINGS_APPEND = '\n\n# --- M-PESA (Safaricom Daraja). Secrets come only from .env. See README, "Phase 4A". -------------------\nMPESA_ENV = env("MPESA_ENV", "sandbox").strip().lower()\nif MPESA_ENV not in ("sandbox", "live"):\n    raise ImproperlyConfigured("MPESA_ENV must be sandbox or live")\nMPESA = {\n    "ENV": MPESA_ENV,\n    "CONSUMER_KEY": env("MPESA_CONSUMER_KEY", ""),\n    "CONSUMER_SECRET": env("MPESA_CONSUMER_SECRET", ""),\n    "SHORTCODE": env("MPESA_SHORTCODE", ""),            # Till: the STORE number. Paybill: the paybill number.\n    "TILL_NUMBER": env("MPESA_TILL_NUMBER", ""),        # Buy Goods till number (customers pay this)\n    "PASSKEY": env("MPESA_PASSKEY", ""),\n    "ACCOUNT_TYPE": env("MPESA_ACCOUNT_TYPE", "till").strip().lower(),   # till | paybill\n    "CALLBACK_BASE_URL": env("MPESA_CALLBACK_BASE_URL", ""),             # public HTTPS address, no trailing slash\n    "CALLBACK_SECRET": env("MPESA_CALLBACK_SECRET", ""),                 # long random text inside the callback path\n    "TIMEOUT": env_int("MPESA_TIMEOUT_SECONDS", 12),\n}\n'
ENV_APPEND = '\n\n# --- M-PESA (Phase 4A). Leave blank until you have Daraja credentials; cash sales never need these. ---\n# sandbox = Safaricom test system, live = real money.\nMPESA_ENV=sandbox\nMPESA_CONSUMER_KEY=\nMPESA_CONSUMER_SECRET=\n# till = Buy Goods (SHORTCODE is the store number, TILL_NUMBER is what customers pay). paybill = SHORTCODE is the paybill.\nMPESA_ACCOUNT_TYPE=till\nMPESA_SHORTCODE=\nMPESA_TILL_NUMBER=\nMPESA_PASSKEY=\n# The public HTTPS address of the server that receives Safaricom\'s messages (your VPS), and a long random secret\n# that becomes part of the callback address. Generate: python -c "import secrets; print(secrets.token_urlsafe(40))"\nMPESA_CALLBACK_BASE_URL=\nMPESA_CALLBACK_SECRET=\nMPESA_TIMEOUT_SECONDS=12\n'
VIEWS_APPEND = '\n\n# --- Phase 4A: M-PESA --------------------------------------------------------------------------------\n\ndef _mpesa_row(txn, total):\n    from django.utils import timezone\n    return {"id": txn.pk, "receipt": txn.trans_id, "amount": str(txn.amount), "name": txn.customer_name,\n            "who": mpesa_rules.phone_hint(txn.payer_ref),\n            "time": timezone.localtime(txn.created_at).strftime("%H:%M"),\n            "matches": total is not None and txn.amount == total}\n\n\n@require_GET\n@login_required_json\n@_guard\ndef mpesa_recent(request, shift):\n    """Confirmed payments nobody has used yet. Exact matches for the current sale come first."""\n    try:\n        total = mpesa_services._cart_total(request.user, shift)[1]\n    except services.SaleError:\n        total = None\n    rows = mpesa_services.recent_unmatched(request.user, shift)\n    rows.sort(key=lambda t: (total is None or t.amount != total))       # stable: newest first inside each group\n    return JsonResponse({"ok": True, "total": str(total) if total is not None else None,\n                         "payments": [_mpesa_row(t, total) for t in rows]})\n\n\n@login_required_json\n@post_json\n@_guard\ndef mpesa_stk_start(request, data, shift):\n    stk = mpesa_services.start_stk(request.user, shift, data.get("phone"))\n    return JsonResponse({"ok": True, "stk_id": stk.pk, "status": stk.status})\n\n\n@require_GET\n@login_required_json\n@_guard\ndef mpesa_stk_status(request, stk_id, shift):\n    stk = mpesa_services.stk_status(request.user, shift, stk_id)\n    return JsonResponse({"ok": True, "status": stk.status, "message": stk.result_desc,\n                         "transaction_id": stk.transaction_id})\n\n\n@login_required_json\n@post_json\n@_guard\ndef checkout_mpesa(request, data, shift):\n    try:\n        transaction_id = int(data.get("transaction_id"))\n    except (TypeError, ValueError):\n        return bad("Choose a payment first.")\n    sale = mpesa_services.checkout_mpesa(request.user, shift, transaction_id)\n    sub = etims.submit(sale.pk)\n    etims.submit_pending(3)\n    return JsonResponse({"ok": True, "sale_id": sale.pk, "number": sale.number, "total": str(sale.total),\n                         "change": "0.00", "customer": sale.customer_name,\n                         "reference": sale.payments.first().reference, "cart": cart_payload(None),\n                         "etims": sub.status if sub else None, "etims_note": sub.last_error if sub else ""})\n'
JS_PAYMENT = '  /* ---------- payment and completion ---------- */\n  function payment() {\n    var c = S.cart; if (!c || !items().length) { say("The sale is empty. Scan a product first.", "err"); return; }\n    var ms = S.cfg.payment_methods;\n    var d = openDialog(\'<h2>Payment method</h2><ul class="opts">\' + ms.map(function (m, i) {\n      return \'<li class="\' + (m.enabled ? "on" : "off") + \'"><span>\' + (i + 1) + ". " + esc(m.label) + "</span><span>" + (m.enabled ? "press " + (i + 1) : "not available yet") + "</span></li>";\n    }).join("") + \'</ul><div class="btns"><button class="ghost" id="py-no" type="button">Back (Esc)</button><button id="py-ok" data-first type="button">Cash (Enter)</button></div>\');\n    function pick(i) { var m = ms[i]; if (!m || !m.enabled) return; closeDialog(d); if (m.code === "MPESA") mpesa(); else complete(); }\n    $("py-ok").onclick = function () { pick(0); }; $("py-no").onclick = function () { closeDialog(d); };\n    d.onKey = function (e) {\n      if (e.key === "Enter") { e.preventDefault(); pick(0); return true; }\n      if (/^[1-9]$/.test(e.key)) { e.preventDefault(); pick(Number(e.key) - 1); return true; }\n      return false;\n    };\n  }\n  function mpesaDone(r) {\n    setCart(r.cart); S.sel = -1; S.lastSale = r.sale_id;\n    var note = "Sale " + r.number + " complete. Paid by M-PESA " + r.reference + (r.customer ? " (" + r.customer + ")" : "") + ".";\n    if (r.etims === "PENDING") note += " eTIMS signature pending (will retry).";\n    else if (r.etims === "REJECTED") note += " eTIMS REJECTED: tell the manager. " + (r.etims_note || "");\n    say(note, r.etims === "REJECTED" ? "err" : "ok");\n    printSale(r.sale_id, false);\n  }\n  function mpesa() {\n    var total = Number(S.cart.total), rows = [], idx = 0, poller = null, stkTimer = null, mcfg = S.cfg.mpesa || {};\n    var d = openDialog(\'<h2>M-PESA payment</h2><div class="grandlbl">Total payable (KES)</div><div class="grand" style="text-align:left">\' + fmt(total) + "</div>" +\n      \'<p class="note">Customer paid to the Till? It shows below within a few seconds. Choose it and press Enter. Only payments confirmed by Safaricom appear here.</p>\' +\n      (mcfg.till_capture ? "" : \'<p class="err">M-PESA capture is not set up on this shop yet. Ask the manager.</p>\') +\n      \'<ul class="opts" id="mp-list"></ul>\' +\n      "<label>Or send a payment request to the customer\'s phone</label>" +\n      \'<input id="mp-phone" inputmode="tel" autocomplete="off" placeholder="0712 345 678"\' + (mcfg.stk ? "" : " disabled") + ">" +\n      \'<div class="note" id="mp-stk">\' + (mcfg.stk ? "" : "Phone requests are not set up. The customer can still pay the Till.") + "</div>" +\n      \'<div class="err" id="mp-err"></div>\' +\n      \'<div class="btns"><button class="ghost" id="mp-no" type="button">Back (Esc)</button><button id="mp-ok" data-first type="button">Use selected payment (Enter)</button></div>\');\n    function alive() { return S.stack.indexOf(d) >= 0; }\n    function paint() {\n      var ul = $("mp-list"); if (!ul) return;\n      if (!rows.length) { ul.innerHTML = \'<li class="off"><span>Waiting for a payment of \' + fmt(total) + "...</span><span></span></li>"; return; }\n      ul.innerHTML = rows.map(function (p, i) {\n        var label = (p.name ? esc(p.name) : "Name not provided") + (p.who ? " " + esc(p.who) : "") + " | " + esc(p.receipt) + " | " + esc(p.time);\n        var right = fmt(Number(p.amount)) + (p.matches ? "" : " (sale is " + fmt(total) + ")");\n        return \'<li class="\' + (p.matches ? "on" : "off") + \'"\' + (i === idx ? \' style="outline:2px solid var(--crimson)"\' : "") + "><span>" + label + "</span><span>" + right + "</span></li>";\n      }).join("");\n    }\n    function poll() {\n      api("GET", "/api/sales/mpesa/recent/").then(function (r) {\n        if (!r.ok || !alive()) return;\n        rows = r.payments || [];\n        var first = -1; rows.forEach(function (p, i) { if (first < 0 && p.matches) first = i; });\n        if (idx >= rows.length || (rows[idx] && !rows[idx].matches && first >= 0)) idx = first >= 0 ? first : 0;\n        paint();\n      });\n    }\n    function apply(id) {\n      if (S.busy) return; S.busy = true;\n      api("POST", "/api/sales/checkout/mpesa/", { transaction_id: id }).then(function (r) {\n        S.busy = false;\n        if (!r.ok) { var er = $("mp-err"); if (er) er.textContent = r.error || "Could not complete the sale."; if (alive()) poll(); return; }\n        if (alive()) closeDialog(d);\n        mpesaDone(r);\n      });\n    }\n    function sendStk() {\n      var phone = $("mp-phone").value.trim(); if (!phone) return;\n      $("mp-err").textContent = ""; $("mp-stk").textContent = "Sending request...";\n      api("POST", "/api/sales/mpesa/stk/", { phone: phone }).then(function (r) {\n        if (!alive()) return;\n        if (!r.ok) { $("mp-stk").textContent = ""; $("mp-err").textContent = r.error || "Could not send the request."; return; }\n        $("mp-stk").textContent = "Request sent. Ask the customer to enter their M-PESA PIN...";\n        clearInterval(stkTimer);\n        stkTimer = setInterval(function () {\n          api("GET", "/api/sales/mpesa/stk/" + r.stk_id + "/").then(function (s) {\n            if (!alive() || !s.ok) return;\n            if (s.status === "CONFIRMED" && s.transaction_id) { clearInterval(stkTimer); apply(s.transaction_id); }\n            else if (s.status === "FAILED" || s.status === "EXPIRED") {\n              clearInterval(stkTimer); $("mp-stk").textContent = "";\n              $("mp-err").textContent = (s.status === "EXPIRED" ? "The customer did not answer. " : "") + (s.message || "The payment did not go through.");\n            }\n          });\n        }, 2500);\n      });\n    }\n    d.onClose = function () { clearInterval(poller); clearInterval(stkTimer); };\n    poller = setInterval(poll, 3000); poll(); paint();\n    $("mp-no").onclick = function () { closeDialog(d); };\n    $("mp-ok").onclick = function () {\n      if (rows[idx] && rows[idx].matches) apply(rows[idx].id);\n      else $("mp-err").textContent = "No payment of KES " + fmt(total) + " has arrived yet.";\n    };\n    d.onKey = function (e) {\n      if (e.key === "ArrowDown") { e.preventDefault(); idx = Math.max(0, Math.min(rows.length - 1, idx + 1)); paint(); return true; }\n      if (e.key === "ArrowUp") { e.preventDefault(); idx = Math.max(0, idx - 1); paint(); return true; }\n      if (e.key === "Enter") { e.preventDefault(); if (document.activeElement === $("mp-phone")) sendStk(); else $("mp-ok").onclick(); return true; }\n      return false;\n    };\n  }\n'
SHIFT_NEW = 'def shift_summary(shift):\n    """A cashier\'s running view of their shift. Cash-up and closing arrive in Phase 5.\n    Only CASH counts towards the drawer: M-PESA and other electronic money never does."""\n    done = Sale.objects.filter(shift=shift, status=Sale.COMPLETED)\n\n    def paid(method):\n        return Payment.objects.filter(sale__in=done, method=method).aggregate(t=Sum("amount"))["t"] or Decimal("0.00")\n\n    cash, mpesa = paid(Payment.CASH), paid(Payment.MPESA)\n    other = paid(Payment.CARD) + paid(Payment.BANK)\n    return {"sales_count": done.count(), "sales_total": str(done.aggregate(t=Sum("total"))["t"] or Decimal("0.00")),\n            "cash_sales": str(cash), "mpesa_sales": str(mpesa), "other_sales": str(other),\n            "opening_float": str(shift.opening_float), "cash_in_drawer_expected": str(shift.opening_float + cash)}\n\n\ndef cart_total(sale):\n    """The amount payable for a cart, worked out from its lines (never trusted from the screen)."""\n    return rules.totals((i.quantity, i.unit_price, i.discount) for i in sale.items.all())[2]\n'
FINISH_HEAD = '    return finish_sale(user, shift, payment={"method": Payment.CASH, "tendered": tendered, "change_given": change})\n\n\n@transaction.atomic\ndef finish_sale(user, shift, *, payment, customer_name=""):\n    """The shared end of every checkout (cash, M-PESA, later card and bank): stock, cost basis, VAT snapshot,\n    the payment record and the gapless sale number, all in ONE transaction. `payment` holds the Payment fields\n    that differ by method (method, reference, tendered, change_given, mpesa_transaction)."""\n    sale = _locked_sale(user, shift)\n    items = list(sale.items.select_related("product"))\n    if not items:\n        raise SaleError("The sale is empty.")\n    subtotal, discount, total = rules.totals((i.quantity, i.unit_price, i.discount) for i in items)\n    if total <= 0:\n        raise SaleError("The total must be more than zero.")\n\n'



class Stop(Exception):
    pass


def once(text, old, new, label):
    if text.count(old) != 1:
        raise Stop(f"{label}: expected the text to appear exactly once, found {text.count(old)}. This file differs from what the installer expects.")
    return text.replace(old, new)


def p_models(t):
    t = once(t, '    CASH = "CASH"\n    METHODS = [(CASH, "Cash")]\n',
             '    CASH, MPESA, CARD, BANK = "CASH", "MPESA", "CARD", "BANK"\n'
             '    METHODS = [(CASH, "Cash"), (MPESA, "M-PESA"), (CARD, "Card"), (BANK, "Bank transfer")]\n', "models: methods")
    t = once(t, '    reference = models.CharField(max_length=60, blank=True)\n',
             '    reference = models.CharField(max_length=60, blank=True)\n'
             '    # Phase 4A: the confirmed M-PESA payment behind this row. One-to-one: a receipt code can pay only one sale.\n'
             '    mpesa_transaction = models.OneToOneField("sales.MpesaTransaction", null=True, blank=True,\n'
             '                                             on_delete=models.PROTECT, related_name="payment")\n', "models: payment field")
    return t.rstrip("\n") + "\n" + MODELS_APPEND


def p_services(t):
    a = t.index("    number_seq = CodeSequence.next(")
    b = t.index("\n\n# --- receipts")
    body = t[a:b].rstrip("\n") + "\n"
    body = once(body, "    Payment.objects.create(sale=sale, method=Payment.CASH, status=Payment.CONFIRMED, amount=total,\n"
                      "                           tendered=tendered, change_given=change, received_by=user)\n",
                "    Payment.objects.create(sale=sale, status=Payment.CONFIRMED, amount=total, received_by=user, **payment)\n", "services: payment")
    body = once(body, "    sale.number, sale.status, sale.completed_at = number, Sale.COMPLETED, now\n",
                "    if customer_name:\n        sale.customer_name = customer_name[:120]\n"
                "    sale.number, sale.status, sale.completed_at = number, Sale.COMPLETED, now\n", "services: name")
    body = once(body, '    sale.save(update_fields=["number", "status", "completed_at", "subtotal", "discount_total", "total",\n'
                      '                             "vat_applied", "tax_total"])',
                '    sale.save(update_fields=["number", "status", "completed_at", "subtotal", "discount_total", "total",\n'
                '                             "vat_applied", "tax_total", "customer_name"])', "services: save")
    body = once(body, '"method": "CASH"', '"method": payment["method"]', "services: audit")
    t = t[:a] + FINISH_HEAD + body + t[b:]
    i = t.index("def shift_summary(shift):")
    return t[:i] + SHIFT_NEW


