PATCHES = [
    ("sales/models.py", p_models), ("sales/services.py", p_services), ("sales/views.py", p_views),
    ("sales/urls.py", p_sales_urls), ("config/urls.py", p_config_urls), ("config/settings.py", p_settings),
    ("core/templates/core/app.html", p_app_html), ("tills/views.py", p_tills_views),
    ("sales/templates/sales/pos.html", p_pos_html), ("core/static/core/theme.css", p_css),
    ("sales/test_phase3b.py", p_old_test), (".env.example", p_env),
]
OPTIONAL = [("staticfiles/core/theme.css", p_css)]       # the collected copy, if present


def main():
    if not (ROOT / "manage.py").exists():
        sys.exit("Put this file next to manage.py and run it again.")
    if (ROOT / "sales" / "mpesa_rules.py").exists():
        sys.exit("Phase 4A looks already installed (sales/mpesa_rules.py exists). Nothing changed.")
    planned = []
    try:
        for rel, fn in PATCHES + [x for x in OPTIONAL if (ROOT / x[0]).exists()]:
            path = ROOT / rel
            if not path.exists():
                raise Stop(f"{rel} is missing.")
            raw = path.read_bytes()
            crlf = b"\r\n" in raw
            text = raw.decode("utf-8").replace("\r\n", "\n")
            new = fn(text)
            planned.append((rel, path, raw, new.replace("\n", "\r\n") if crlf else new))
    except (Stop, ValueError) as exc:
        sys.exit(f"STOPPED, nothing was changed.\n  {exc}")
    backup = ROOT / "_phase4a_backup"
    for rel, path, raw, new in planned:
        dest = backup / rel
        dest.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(path, dest)
        path.write_bytes(new.encode("utf-8"))
        print("patched ", rel)
    for rel, text in NEW_FILES.items():
        path = ROOT / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8", newline="\n")
        print("created ", rel)
    print("\nDone. Originals are in _phase4a_backup/.\nNext:\n  python manage.py makemigrations sales\n  python manage.py migrate\n"
          "  python manage.py collectstatic --noinput\n  DB_ENGINE=sqlite DJANGO_DEBUG=true python manage.py test sales   (Windows: set the two variables first)\n"
          "Then read PHASE4_NOTES.md.")


if __name__ == "__main__":
    main()